export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  url: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  isPost: boolean;
}

export interface SiteConfig {
  title: string;
  description: string;
  baseUrl: string;
  language: string;
}

export interface BuildContext {
  pages: Page[];
  tags: Map<string, Page[]>;
  config: SiteConfig;
  startTime: Date;
}

import matter from "gray-matter";
import MarkdownIt from "markdown-it";
import hljs from "highlight.js";
import type { Page, Frontmatter } from "./types.js";

const md = new MarkdownIt({
  html: true,
  highlight(str: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      try {
        return (
          '<pre><code class="hljs language-' +
          lang +
          '">' +
          hljs.highlight(str, { language: lang, ignoreIllegals: true }).value +
          "</code></pre>"
        );
      } catch {
        // fall through
      }
    }
    return '<pre><code class="hljs">' + md.utils.escapeHtml(str) + "</code></pre>";
  },
});

export function parseMarkdown(raw: string, filePath: string): Page {
  const { data, content } = matter(raw);

  const frontmatter: Frontmatter = {
    title: data.title ?? "Untitled",
    date: data.date ? String(data.date) : undefined,
    tags: parseTags(data.tags),
    draft: data.draft === true || data.draft === "true",
  };

  for (const [k, v] of Object.entries(data)) {
    if (!(k in frontmatter)) {
      frontmatter[k] = v;
    }
  }

  const html = md.render(content);
  const url = filePathToUrl(filePath);
  const isPost = filePath.startsWith("posts/") || filePath.startsWith("/posts/");

  return { path: filePath, url, frontmatter, content, html, isPost };
}

function parseTags(tags: unknown): string[] {
  if (Array.isArray(tags)) return tags.map(String);
  if (typeof tags === "string") return tags.split(",").map((t) => t.trim()).filter(Boolean);
  return [];
}

function filePathToUrl(filePath: string): string {
  let url = filePath.replace(/\\/g, "/");
  url = url.replace(/^\.?\//, "");
  if (url.endsWith(".md")) url = url.slice(0, -3);
  if (url.endsWith("/index")) url = url.slice(0, -5) || "/";
  if (url === "index") url = "";
  return "/" + url.replace(/\/$/, "") + "/";
}

import Handlebars from "handlebars";
import { readFile } from "node:fs/promises";
import { join, dirname, basename } from "node:path";
import { glob } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import type { Page, BuildContext } from "./types.js";

export async function loadTemplates(templateDir: string): Promise<void> {
  Handlebars.registerHelper("formatDate", (date: string) => {
    if (!date) return "";
    const d = new Date(date);
    if (isNaN(d.getTime())) return date;
    return d.toISOString().split("T")[0];
  });

  Handlebars.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  Handlebars.registerHelper("hasTag", (tags: string[], tag: string) =>
    Array.isArray(tags) ? tags.includes(tag) : false,
  );

  const pattern = join(templateDir, "**/*.hbs").replace(/\\/g, "/");
  const files: string[] = [];
  for await (const f of glob(pattern)) {
    files.push(f);
  }

  for (const file of files) {
    const content = await readFile(file, "utf-8");
    const relative = file.replace(templateDir, "").replace(/^[/\\]/, "");
    const name = relative.replace(/\.hbs$/, "").replace(/\\/g, "/");

    if (name.startsWith("partials/")) {
      const partialName = name.replace("partials/", "");
      Handlebars.registerPartial(partialName, content);
    } else {
      Handlebars.registerPartial(name, content);
    }

    Handlebars.compile(content);
  }

  Handlebars.registerHelper("tagList", function (context: BuildContext) {
    const tags = [...context.tags.keys()].sort();
    let html = '<ul class="tag-list">';
    for (const tag of tags) {
      const count = context.tags.get(tag)!.length;
      html += `<li><a href="/tags/${tag}/">${tag}</a> (${count})</li>`;
    }
    html += "</ul>";
    return new Handlebars.SafeString(html);
  });

  Handlebars.registerHelper("tagCloud", function (context: BuildContext) {
    const entries = [...context.tags.entries()].sort((a, b) => a[0].localeCompare(b[0]));
    const max = Math.max(...entries.map(([, pages]) => pages.length), 1);
    let html = '<ul class="tag-cloud">';
    for (const [tag, pages] of entries) {
      const size = 80 + Math.round((pages.length / max) * 120);
      html += `<li style="font-size:${size}%"><a href="/tags/${tag}/">${tag}</a></li>`;
    }
    html += "</ul>";
    return new Handlebars.SafeString(html);
  });

  Handlebars.registerHelper("rssDate", (date: string) => {
    if (!date) return "";
    return date;
  });
}

function templateFor(name: string): HandlebarsTemplateDelegate | undefined {
  try {
    return Handlebars.compile(`{{> ${name}}}`);
  } catch {
    return undefined;
  }
}

export function renderPage(page: Page, context: BuildContext): string {
  const tplName = page.isPost ? "post" : (page.path === "posts/index.md" ? "index" : undefined);
  let tpl = tplName ? templateFor(tplName) : undefined;

  if (!tpl) {
    tpl = templateFor("default");
  }
  if (!tpl) {
    tpl = Handlebars.compile("{{{html}}}");
  }

  const layoutTpl = templateFor("layout");

  const innerHtml = tpl({ page, context });

  if (layoutTpl) {
    return layoutTpl({ page, context, body: new Handlebars.SafeString(innerHtml) });
  }

  return innerHtml;
}

export function renderString(template: string, data: Record<string, unknown>): string {
  const compiled = Handlebars.compile(template);
  return compiled(data);
}

import RSS from "rss";
import type { Page, BuildContext } from "./types.js";

export function generateRss(context: BuildContext): string {
  const posts = context.pages
    .filter((p) => p.isPost && !p.frontmatter.draft && p.frontmatter.date)
    .sort((a, b) => {
      const da = new Date(a.frontmatter.date!).getTime();
      const db = new Date(b.frontmatter.date!).getTime();
      return db - da;
    });

  const feed = new RSS({
    title: context.config.title,
    description: context.config.description,
    feed_url: `${context.config.baseUrl}/feed.xml`,
    site_url: context.config.baseUrl,
    language: context.config.language,
    pubDate: posts[0]?.frontmatter.date ?? new Date().toISOString(),
  });

  for (const post of posts) {
    feed.item({
      title: post.frontmatter.title,
      description: post.html,
      url: `${context.config.baseUrl}${post.url}`,
      date: post.frontmatter.date,
      categories: post.frontmatter.tags,
      author: post.frontmatter.author as string | undefined,
    });
  }

  return feed.xml({ indent: true });
}

import { readFile, writeFile, mkdir, readdir } from "node:fs/promises";
import { join, relative, dirname } from "node:path";
import { glob } from "node:fs/promises";
import { parseMarkdown } from "./markdown.js";
import { loadTemplates, renderPage } from "./templates.js";
import { generateRss } from "./rss.js";
import type { Page, BuildContext, SiteConfig } from "./types.js";

const LIVE_RELOAD_SCRIPT = `
<script>
(function(){
  if (window.__ssgLiveReload) return;
  window.__ssgLiveReload = true;
  var ws = new WebSocket('ws://' + location.hostname + ':35729');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      window.__ssgLiveReload = false;
    }, 2000);
  };
})();
</script>
`;

export async function buildSite(
  srcDir: string,
  templateDir: string,
  outDir: string,
  config: SiteConfig,
  injectReload = false,
): Promise<BuildContext> {
  const startTime = new Date();

  await loadTemplates(templateDir);

  const pattern = join(srcDir, "**/*.md").replace(/\\/g, "/");
  const files: string[] = [];
  for await (const f of glob(pattern)) {
    files.push(f);
  }

  const pages: Page[] = [];
  for (const file of files) {
    const raw = await readFile(file, "utf-8");
    const relPath = file.replace(srcDir, "").replace(/^[/\\]/, "");
    const page = parseMarkdown(raw, relPath);
    if (!page.frontmatter.draft || page.isPost) {
      pages.push(page);
    }
  }

  const tags = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags ?? []) {
      const list = tags.get(tag) || [];
      list.push(page);
      tags.set(tag, list);
    }
  }

  const context: BuildContext = { pages, tags, config, startTime };

  for (const page of pages) {
    const html = renderPage(page, context);
    let fullHtml = html;
    if (injectReload) {
      fullHtml = html.replace("</body>", LIVE_RELOAD_SCRIPT + "</body>");
      if (fullHtml === html) {
        fullHtml = html + LIVE_RELOAD_SCRIPT;
      }
    }
    await writeOutput(outDir, page.url, fullHtml);
  }

  for (const [tag] of tags) {
    const tagUrl = `/tags/${tag}/`;
    const tagHtml = renderTagIndex(tag, context);
    let fullHtml = tagHtml;
    if (injectReload) {
      fullHtml = tagHtml.replace("</body>", LIVE_RELOAD_SCRIPT + "</body>");
      if (fullHtml === tagHtml) {
        fullHtml = tagHtml + LIVE_RELOAD_SCRIPT;
      }
    }
    await writeOutput(outDir, tagUrl, fullHtml);
  }

  const tagsIndexHtml = renderTagsIndex(context);
  let fullTagsHtml = tagsIndexHtml;
  if (injectReload) {
    fullTagsHtml = tagsIndexHtml.replace("</body>", LIVE_RELOAD_SCRIPT + "</body>");
    if (fullTagsHtml === tagsIndexHtml) {
      fullTagsHtml = tagsIndexHtml + LIVE_RELOAD_SCRIPT;
    }
  }
  await writeOutput(outDir, "/tags/", fullTagsHtml);

  const rss = generateRss(context);
  await writeOutput(outDir, "/feed.xml", rss, "application/xml");

  const notFoundHtml = renderNotFound(context);
  await writeOutput(outDir, "/404/", notFoundHtml);

  return context;
}

function renderTagIndex(tag: string, context: BuildContext): string {
  const tagged = (context.tags.get(tag) ?? []).filter(
    (p) => !p.frontmatter.draft,
  );
  const posts = tagged
    .filter((p) => p.frontmatter.date)
    .sort((a, b) => new Date(b.frontmatter.date!).getTime() - new Date(a.frontmatter.date!).getTime());

  const body = `
<h1>Tag: ${tag}</h1>
<ul>
${posts.map((p) => `<li><a href="${p.url}">${p.frontmatter.title}</a>${p.frontmatter.date ? ` — ${p.frontmatter.date}` : ""}</li>`).join("\n")}
</ul>
`;
  return body;
}

function renderTagsIndex(context: BuildContext): string {
  const entries = [...context.tags.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  const body = `
<h1>Tags</h1>
<ul>
${entries.map(([tag, pages]) => `<li><a href="/tags/${tag}/">${tag}</a> (${pages.length})</li>`).join("\n")}
</ul>
`;
  return body;
}

function renderNotFound(context: BuildContext): string {
  return `<h1>404 — Not Found</h1><p>The page you requested does not exist.</p>`;
}

async function writeOutput(
  outDir: string,
  url: string,
  content: string,
  mimeType = "text/html",
): Promise<void> {
  let dir = outDir;
  let filename = "index.html";

  if (url.endsWith(".xml")) {
    filename = url.split("/").pop()!;
    dir = join(outDir, ...url.split("/").slice(0, -1).filter(Boolean));
  } else {
    const parts = url.split("/").filter(Boolean);
    if (parts.length > 0) {
      dir = join(outDir, ...parts);
    }
  }

  await mkdir(dir, { recursive: true });
  await writeFile(join(dir, filename), content, "utf-8");
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { watch } from "chokidar";
import { buildSite } from "./build.js";
import type { SiteConfig } from "./types.js";

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".xml": "application/xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".woff2": "font/woff2",
};

let sockets = new Set<WebSocket>();

export async function startServer(
  outDir: string,
  srcDir: string,
  templateDir: string,
  config: SiteConfig,
  port: number,
): Promise<void> {
  const wss = new WebSocketServer({ port: 35729 });

  wss.on("connection", (ws) => {
    sockets.add(ws);
    ws.on("close", () => sockets.delete(ws));
  });

  function reload() {
    for (const ws of sockets) {
      ws.send("reload");
    }
  }

  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
    let urlPath = req.url ?? "/";
    if (urlPath === "/") urlPath = "/index.html";

    const filePath = join(outDir, urlPath);
    try {
      await stat(filePath);
      const ext = extname(filePath).toLowerCase();
      const mime = MIME_TYPES[ext] ?? "application/octet-stream";
      const content = await readFile(filePath);
      res.writeHead(200, { "Content-Type": mime });
      res.end(content);
    } catch {
      try {
        const notFoundPath = join(outDir, "404", "index.html");
        const content = await readFile(notFoundPath);
        res.writeHead(404, { "Content-Type": "text/html" });
        res.end(content);
      } catch {
        res.writeHead(404, { "Content-Type": "text/plain" });
        res.end("404 Not Found");
      }
    }
  });

  const watcher = watch([srcDir, templateDir], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 200, pollInterval: 50 },
  });

  let rebuildTimeout: ReturnType<typeof setTimeout> | null = null;

  watcher.on("all", async (_event, _path) => {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(async () => {
      try {
        await buildSite(srcDir, templateDir, outDir, config, true);
        reload();
        console.log("[ssg] Rebuilt site");
      } catch (err) {
        console.error("[ssg] Build error:", err);
      }
    }, 300);
  });

  server.listen(port, () => {
    console.log(`[ssg] Dev server running at http://localhost:${port}`);
  });
}

#!/usr/bin/env node

import { Command } from "commander";
import { resolve } from "node:path";
import { buildSite } from "./build.js";
import { startServer } from "./server.js";
import type { SiteConfig } from "./types.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator CLI")
  .version("1.0.0")
  .option("-s, --source <dir>", "Source directory of Markdown files", "src")
  .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "Output directory for generated HTML", "dist")
  .option("--title <title>", "Site title", "My Site")
  .option("--description <desc>", "Site description", "A static site")
  .option("--base-url <url>", "Base URL for RSS feeds", "http://localhost:3000")
  .option("--language <lang>", "Site language", "en")
  .option("--serve", "Start a dev server with live reload")
  .option("-p, --port <port>", "Dev server port", "3000")
  .action(async (options) => {
    const srcDir = resolve(process.cwd(), options.source);
    const templateDir = resolve(process.cwd(), options.templates);
    const outDir = resolve(process.cwd(), options.output);
    const port = parseInt(options.port, 10);

    const config: SiteConfig = {
      title: options.title,
      description: options.description,
      baseUrl: options.baseUrl,
      language: options.language,
    };

    console.log(`[ssg] Building site...`);

    try {
      if (options.serve) {
        await buildSite(srcDir, templateDir, outDir, config, true);
        await startServer(srcDir, templateDir, outDir, config, port);
      } else {
        const ctx = await buildSite(srcDir, templateDir, outDir, config);
        const elapsed = ((Date.now() - ctx.startTime.getTime()) / 1000).toFixed(2);
        console.log(
          `[ssg] Built ${ctx.pages.length} pages and ${ctx.tags.size} tag pages in ${elapsed}s`,
        );
      }
    } catch (err) {
      console.error("[ssg] Error:", err);
      process.exit(1);
    }
  });

program.parse();

import { describe, it, expect } from "vitest";
import { parseMarkdown } from "../src/markdown.js";

describe("parseMarkdown", () => {
  it("parses YAML frontmatter fields", () => {
    const raw = `---
title: My Post
date: "2025-03-10"
tags:
  - typescript
  - ssg
draft: false
---

# Content

Hello world.
`;
    const page = parseMarkdown(raw, "posts/my-post.md");

    expect(page.frontmatter.title).toBe("My Post");
    expect(page.frontmatter.date).toBe("2025-03-10");
    expect(page.frontmatter.tags).toEqual(["typescript", "ssg"]);
    expect(page.frontmatter.draft).toBe(false);
    expect(page.isPost).toBe(true);
  });

  it("defaults title to Untitled when missing", () => {
    const raw = `---
date: 2025-01-01
---

Text.
`;
    const page = parseMarkdown(raw, "posts/no-title.md");
    expect(page.frontmatter.title).toBe("Untitled");
  });

  it("parses comma-separated tags string", () => {
    const raw = `---
title: Post
tags: "js, css, html"
---

Text.
`;
    const page = parseMarkdown(raw, "posts/comma-tags.md");
    expect(page.frontmatter.tags).toEqual(["js", "css", "html"]);
  });

  it("handles draft as boolean", () => {
    const raw = `---
title: Drafty
draft: true
---

Content.
`;
    const page = parseMarkdown(raw, "posts/drafty.md");
    expect(page.frontmatter.draft).toBe(true);
  });

  it("handles draft as string", () => {
    const raw = `---
title: Drafty
draft: "true"
---

Content.
`;
    const page = parseMarkdown(raw, "posts/drafty-str.md");
    expect(page.frontmatter.draft).toBe(true);
  });

  it("produces correct URL from file path", () => {
    const raw = `---
title: A Post
---

Text.
`;
    const page = parseMarkdown(raw, "posts/nested/deep-post.md");
    expect(page.url).toBe("/posts/nested/deep-post/");
  });

  it("handles index.md specially", () => {
    const raw = `---
title: Index
---

Home.
`;
    const page = parseMarkdown(raw, "index.md");
    expect(page.url).toBe("/");
  });

  it("syntax highlights code blocks", () => {
    const raw = `---
title: Code
---

\`\`\`js
const x = 1;
\`\`\`
`;
    const page = parseMarkdown(raw, "posts/code.md");
    expect(page.html).toContain("language-js");
    expect(page.html).toContain("hljs");
  });

  it("escapes unknown languages", () => {
    const raw = `---
title: Code
---

\`\`\`fakelang
some code
\`\`\`
`;
    const page = parseMarkdown(raw, "posts/fake.md");
    expect(page.html).toContain("<pre><code");
    expect(page.html).not.toContain("language-fakelang");
  });

  it("marks non-posts paths as not posts", () => {
    const raw = `---
title: About
---

About us.
`;
    const page = parseMarkdown(raw, "about.md");
    expect(page.isPost).toBe(false);
  });

  it("preserves extra frontmatter keys", () => {
    const raw = `---
title: Extra
author: Jane Doe
custom: value
---

Text.
`;
    const page = parseMarkdown(raw, "posts/extra.md");
    expect(page.frontmatter.author).toBe("Jane Doe");
    expect(page.frontmatter.custom).toBe("value");
  });
});

import { describe, it, expect, beforeAll } from "vitest";
import { loadTemplates, renderString, renderPage } from "../src/templates.js";
import { parseMarkdown } from "../src/markdown.js";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import type { BuildContext } from "../src/types.js";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const fixtureTemplates = resolve(__dirname, "fixtures/templates");

const mockContext: BuildContext = {
  pages: [],
  tags: new Map(),
  config: {
    title: "Test Site",
    description: "A test",
    baseUrl: "http://localhost:3000",
    language: "en",
  },
  startTime: new Date(),
};

describe("templates", () => {
  beforeAll(async () => {
    await loadTemplates(fixtureTemplates);
  });

  it("renders a simple template", () => {
    const result = renderString("Hello {{name}}!", { name: "World" });
    expect(result).toBe("Hello World!");
  });

  it("formats dates with the formatDate helper", () => {
    const result = renderString("{{formatDate date}}", {
      date: "2025-03-15",
    });
    expect(result).toBe("2025-03-15");
  });

  it("handles missing dates gracefully", () => {
    const result = renderString("{{formatDate date}}", { date: null });
    expect(result).toBe("");
  });

  it("eq helper returns true for equal values", () => {
    const result = renderString("{{#if (eq a b)}}yes{{else}}no{{/if}}", {
      a: "foo",
      b: "foo",
    });
    expect(result).toBe("yes");
  });

  it("eq helper returns false for different values", () => {
    const result = renderString("{{#if (eq a b)}}yes{{else}}no{{/if}}", {
      a: "foo",
      b: "bar",
    });
    expect(result).toBe("no");
  });

  it("renders a page using the post template", () => {
    const raw = `---
title: Template Test
date: 2025-02-20
tags:
  - test
---

Post content.
`;
    const page = parseMarkdown(raw, "posts/template-test.md");
    const html = renderPage(page, mockContext);

    expect(html).toContain("Template Test");
    expect(html).toContain("Test Site");
    expect(html).toContain("<article>");
  });

  it("renders a page with the layout wrapping", () => {
    const raw = `---
title: With Layout
---

Layout content.
`;
    const page = parseMarkdown(raw, "posts/layout-test.md");
    const html = renderPage(page, mockContext);

    expect(html).toContain("<!DOCTYPE html>");
    expect(html).toContain("<main>");
    expect(html).toContain("With Layout");
    expect(html).toContain("Test Site");
  });
});

import { describe, it, expect, afterEach } from "vitest";
import { execSync } from "node:child_process";
import { existsSync, rmSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const rootDir = resolve(__dirname, "..");
const outDir = resolve(rootDir, "test-output");
const cliEntry = resolve(rootDir, "dist/index.js");

const fixtureSrc = resolve(__dirname, "fixtures/src");
const fixtureTemplates = resolve(__dirname, "fixtures/templates");

function runSsg(args: string): string {
  return execSync(`node ${cliEntry} ${args}`, {
    cwd: rootDir,
    encoding: "utf-8",
    env: { ...process.env, NODE_NO_WARNINGS: "1" },
  });
}

describe("CLI flags", () => {
  afterEach(() => {
    if (existsSync(outDir)) {
      rmSync(outDir, { recursive: true, force: true });
    }
  });

  it("shows help text with --help", () => {
    const output = runSsg("--help");
    expect(output).toContain("Static site generator");
